// WF09 v2 - Validación del payload + preparación de derivados.
//
// expected_participants: lo que esperamos que esté en el grupo tras crearlo.
//   Roles: lead | closer | stakeholder. NO incluye al SDR (es el creador y
//   siempre está dentro automáticamente).
//
// messages: array de strings (3 ó 5) listos para enviar al grupo cuando todos
//   los expected estén dentro. Se guardan a Supabase para que WF09b los pueda
//   enviar si vienen tarde.

const EVOAPI_BASE_URL = 'https://cioevolutionapiapp.nexau.es';
const EVOAPI_INSTANCE = 'Leon-Test';
const GROUP_PICTURE_URL = 'https://drive.google.com/uc?export=download&id=1WRAzcFPSphrJCaEgPUWcMFCJh4TuIuup';

const VIDEO_BY_SEGMENT = {
  genesis: 'https://privado.consultoria.io/nuestra-estrategia',
  mega:    'https://ia.consultoria.io/proceso-en-detalle',
};

function normalizePhone(raw) {
  if (!raw) return null;
  const digits = String(raw).replace(/\D/g, '');
  if (digits.length < 8) return null;
  return digits;
}

function fail(msg) { throw new Error('WF09 payload error: ' + msg); }

const payload = $input.first().json.body || $input.first().json;
const required = ['lead_id', 'lead_name', 'lead_phone', 'lead_company', 'meeting_url', 'meeting_at', 'segment'];
for (const k of required) { if (!payload[k]) fail('missing field ' + k); }

const lead_phone = normalizePhone(payload.lead_phone);
if (!lead_phone) fail('lead_phone is not a valid E.164 number');

let closer = null;
if (payload.closer_name || payload.closer_phone) {
  if (!payload.closer_name || !payload.closer_phone) fail('closer_name and closer_phone must both be provided together');
  const closer_phone = normalizePhone(payload.closer_phone);
  if (!closer_phone) fail('closer_phone is not a valid E.164 number');
  closer = { name: payload.closer_name, phone: closer_phone };
}

const segment = String(payload.segment).toLowerCase();
if (!VIDEO_BY_SEGMENT[segment]) fail('segment must be genesis or mega, got ' + segment);
const video_url = VIDEO_BY_SEGMENT[segment];

const stakeholders = Array.isArray(payload.stakeholders) ? payload.stakeholders : [];
const stakeholder_phones = [];
for (const sh of stakeholders) {
  const p = normalizePhone(sh.phone);
  if (!p) fail('stakeholder phone invalid: ' + JSON.stringify(sh));
  stakeholder_phones.push(p);
}

const meetingDate = new Date(payload.meeting_at);
if (isNaN(meetingDate.getTime())) fail('meeting_at is not a valid ISO date');
const fmtMadridParts = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(meetingDate).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
const dateStr = `${fmtMadridParts.day}/${fmtMadridParts.month}/${fmtMadridParts.year}`;
const hourLabel = fmtMadridParts.hour + 'h';
const group_subject = `${payload.lead_company} x C.io - ${dateStr} a las ${hourLabel}`;

const participants = [lead_phone, ...stakeholder_phones];
if (closer) participants.unshift(closer.phone);

const expected_participants = [
  { phone: lead_phone, name: payload.lead_name, role: 'lead' },
  ...(closer ? [{ phone: closer.phone, name: closer.name, role: 'closer' }] : []),
  ...stakeholders.map((sh, i) => ({ phone: stakeholder_phones[i], name: sh.name || ('stakeholder #' + (i+1)), role: 'stakeholder' })),
];

const lead = { id: payload.lead_id, name: payload.lead_name, phone: lead_phone, company: payload.lead_company };
const meeting = { url: payload.meeting_url, at_iso: payload.meeting_at, date_madrid: dateStr };

const messages = closer
  ? [
      `Hola ${lead.name}, ${closer.name}, os presento`,
      `${lead.name} es el fundador de ${lead.company}`,
      `${closer.name} es uno de nuestros consultores expertos en ecommerce`,
      `Os dejo por aquí el enlace para la reunión: ${meeting.url}`,
      `Por cierto, ${lead.name}, te dejo por aquí el vídeo que te había comentado para que puedas verlo antes de la llamada ${video_url}`,
    ]
  : [
      `Hola ${lead.name} 👋`,
      `Te dejo por aquí el enlace para la reunión: ${meeting.url}`,
      `Por cierto, te dejo por aquí el vídeo que te había comentado para que puedas verlo antes de la llamada ${video_url}`,
    ];

return [{
  json: {
    config: { evoapi_base_url: EVOAPI_BASE_URL, evoapi_instance: EVOAPI_INSTANCE, group_picture_url: GROUP_PICTURE_URL },
    hubspot_lead_id: payload.lead_id,
    lead,
    closer,
    meeting,
    segment,
    video_url,
    group_subject,
    participants,
    expected_participants,
    stakeholder_phones,
    messages,
  }
}];

// WF09 v2 - Decisión: ¿todos dentro o algunos pendientes?
//
// Output: N items para el siguiente Send text. Si todos dentro → items son
// los mensajes del SOP al grupo. Si falta alguien → items son invites 1-1
// a cada pending. El campo `decision` marca el modo para que Aggregate sepa
// qué state guardar y qué timestamp poblar.

const validated = $('Validate payload').first().json;
const groupResp = $('Create group').first().json;
const groupInfo = $('Get group participants').first().json;
const inviteResp = $('Get invite URL').first().json;

const groupJid = groupResp?.id;
if (!groupJid) throw new Error('Decide: no groupJid');

// inviteCode endpoint devuelve { inviteCode: '...', inviteUrl: 'https://chat.whatsapp.com/...' }
// Tomamos inviteUrl si existe; fallback a construirla desde inviteCode.
let inviteUrl = inviteResp?.inviteUrl || inviteResp?.invite_url;
if (!inviteUrl && inviteResp?.inviteCode) inviteUrl = 'https://chat.whatsapp.com/' + inviteResp.inviteCode;
if (!inviteUrl) throw new Error('Decide: no invite URL in response: ' + JSON.stringify(inviteResp).slice(0,300));

// Sacar lista de phones que ESTÁN dentro (excluyendo al SDR creador).
// groupInfo.participants[].phoneNumber tiene formato '34XXX@s.whatsapp.net'.
const joinedPhones = new Set();
for (const p of (groupInfo?.participants || [])) {
  const pn = (p.phoneNumber || '').split('@')[0];
  if (pn) joinedPhones.add(pn);
}

// Pending = expected pero NO joined
const pending = validated.expected_participants.filter(ep => !joinedPhones.has(ep.phone));
const joinedAt = {};
const now = new Date().toISOString();
for (const ep of validated.expected_participants) {
  if (joinedPhones.has(ep.phone)) joinedAt[ep.phone] = now;
}

const decision = pending.length === 0 ? 'all_present' : 'pending_join';

let items;
if (decision === 'all_present') {
  // Modo happy: mandar mensajes SOP al groupJid
  items = validated.messages.map((text, i) => ({
    json: {
      _meta: { decision, group_jid: groupJid, invite_url: inviteUrl, joined_at: joinedAt, pending },
      number: groupJid,
      text,
      idx: i + 1,
    }
  }));
} else {
  // Modo pending: mandar invite 1-1 a cada uno
  const sdrIsCreator = true; // el SDR es el dueño de la sesión EvoAPI
  items = pending.map((ep, i) => {
    const greeting = ep.role === 'lead'
      ? `Hola ${ep.name}, soy del equipo de Consultoría.io. Como tu configuración de privacidad no me permitió añadirte directamente al grupo de la llamada, te paso el enlace para que entres tú mismo y nos pongamos en marcha: ${inviteUrl}`
      : `Hola ${ep.name}, no he podido añadirte directamente al grupo del lead (${validated.lead.name}, ${validated.lead.company}). Entra aquí: ${inviteUrl}`;
    return {
      json: {
        _meta: { decision, group_jid: groupJid, invite_url: inviteUrl, joined_at: joinedAt, pending },
        number: ep.phone,
        text: greeting,
        idx: i + 1,
      }
    };
  });
}

return items;

// WF09 v2 - Combina respuestas de Send text + prepara la row para INSERT.
//
// Output: un único item con todos los campos que el siguiente nodo Supabase
// va a meter en cl001_p007_precall_nurturing_wa_groups. State depende de la
// decisión: messages_sent si modo all_present, awaiting_join si pending_join.

const responses = $input.all();
const built = $('Decide messages vs invites').all();
const validated = $('Validate payload').first().json;
const meta = built[0]?.json?._meta || {};
const { decision, group_jid, invite_url, joined_at, pending } = meta;

const sent = [];
for (let i = 0; i < responses.length; i++) {
  const r = responses[i];
  const errObj = r.json?.error || r.error;
  sent.push({
    index: i + 1,
    ok: !errObj,
    target: built[i]?.json?.number,
    text_preview: (built[i]?.json?.text || '').slice(0, 80),
    message_id: r.json?.key?.id || r.json?.id || null,
    error: errObj ? (errObj.message || String(errObj)) : undefined,
  });
}

const nowIso = new Date().toISOString();
const state = decision === 'all_present' ? 'messages_sent' : 'awaiting_join';

// Stakeholder phones simple list para fácil query
const stakeholderPhones = validated.expected_participants
  .filter(p => p.role === 'stakeholder')
  .map(p => p.phone);

// Row a insertar — los campos JSONB se serializan abajo en el nodo Supabase
const row = {
  hubspot_lead_id: validated.hubspot_lead_id,
  group_jid,
  group_subject: validated.group_subject,
  invite_url,
  lead_phone: validated.lead.phone,
  lead_name: validated.lead.name,
  lead_company: validated.lead.company,
  closer_phone: validated.closer?.phone || null,
  closer_name: validated.closer?.name || null,
  stakeholder_phones: stakeholderPhones,
  expected_participants: validated.expected_participants,
  pending_participants: pending,
  joined_at,
  meeting_url: validated.meeting.url,
  meeting_at: validated.meeting.at_iso,
  segment: validated.segment,
  video_url: validated.video_url,
  messages: validated.messages,
  state,
  messages_sent_at: state === 'messages_sent' ? nowIso : null,
  sent_results: state === 'messages_sent' ? sent : null,
  invite_sent_at: state === 'awaiting_join' ? nowIso : null,
};

return [{
  json: {
    // Para el INSERT
    ...row,
    // Para el response al webhook + observabilidad
    _response: {
      ok: sent.length > 0 && sent.every(s => s.ok),
      decision,
      state,
      group_jid,
      group_subject: validated.group_subject,
      invite_url,
      pending: pending.map(p => ({ phone: p.phone, name: p.name, role: p.role })),
      sent,
    }
  }
}];
